// Generated from the former 0001_init.sql; inlined so the SDK bundles without runtime file reads.
export const sql = "-- Vlo journal, Postgres.\n--\n-- Every object is unqualified on purpose: the journal connects with\n-- `search_path = <schema>` (default `vlo`) and creates that schema before this\n-- file runs, so nothing here can reach `public`.\n--\n-- Hashed or replayed JSON (`state`, `kernel_state`, `payload`, `input`,\n-- `output`, `schemas.retry_policy`) is `text`, never `jsonb`: jsonb rewrites key\n-- order and numeric lexemes, which would break re-fold equality.\n-- Every instant is a `bigint` millisecond epoch named `*_ms`, so Postgres,\n-- SQLite and the TypeScript rows agree on one representation.\n\nCREATE TABLE IF NOT EXISTS migrations (\n  version       text PRIMARY KEY,\n  applied_at_ms bigint NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS runs (\n  run_id                  text PRIMARY KEY,\n  namespace               text NOT NULL DEFAULT 'default',\n  workflow                text NOT NULL,\n  component_digest        text NOT NULL,\n  status                  text NOT NULL,\n  last_seq                bigint NOT NULL DEFAULT 0,\n  parent_run_id           text,\n  parent_step_id          text,\n  continued_from          text,\n  input                   text,\n  input_ref               text,\n  output                  text,\n  output_ref              text,\n  search                  jsonb NOT NULL DEFAULT '{}',\n  assignee                text,\n  created_at_ms           bigint NOT NULL,\n  updated_at_ms           bigint NOT NULL,\n  started_at_ms           bigint,\n  closed_at_ms            bigint,\n  parent_notified_at_ms   bigint,\n  start_claimed_until_ms  bigint,\n  notify_claimed_until_ms bigint\n);\n\n-- Outbox stage \"start runs\".\nCREATE INDEX IF NOT EXISTS runs_created_idx\n  ON runs (created_at_ms) WHERE status = 'created';\n\n-- Outbox stage \"notify parents\".\nCREATE INDEX IF NOT EXISTS runs_notify_idx\n  ON runs (closed_at_ms)\n  WHERE parent_run_id IS NOT NULL AND parent_notified_at_ms IS NULL;\n\nCREATE INDEX IF NOT EXISTS runs_query_idx ON runs (namespace, status, created_at_ms);\nCREATE INDEX IF NOT EXISTS runs_search_idx ON runs USING gin (search);\n\nCREATE TABLE IF NOT EXISTS events (\n  run_id         text NOT NULL REFERENCES runs (run_id) ON DELETE CASCADE,\n  seq            bigint NOT NULL,\n  step_id        text NOT NULL,\n  attempt        integer NOT NULL,\n  kind           text NOT NULL,\n  status         text NOT NULL,\n  cause          text,\n  schema_ref     text,\n  payload        text,\n  payload_ref    text,\n  error          text,\n  usage          jsonb,\n  random         text NOT NULL,\n  state_hash     text NOT NULL,\n  parent_run_id  text,\n  parent_step_id text,\n  ts_ms          bigint NOT NULL,\n  PRIMARY KEY (run_id, seq)\n);\n\nCREATE TABLE IF NOT EXISTS run_state (\n  run_id        text PRIMARY KEY REFERENCES runs (run_id) ON DELETE CASCADE,\n  seq           bigint NOT NULL,\n  bundle_digest text NOT NULL,\n  kernel_state  text NOT NULL,\n  state         text,\n  state_ref     text,\n  state_hash    text NOT NULL,\n  CONSTRAINT run_state_one_body CHECK ((state IS NULL) <> (state_ref IS NULL))\n);\n\nCREATE TABLE IF NOT EXISTS tasks (\n  task_id                   text PRIMARY KEY,\n  run_id                    text NOT NULL REFERENCES runs (run_id) ON DELETE CASCADE,\n  step_id                   text NOT NULL,\n  attempt                   integer NOT NULL,\n  activity                  text NOT NULL,\n  schema_ref                text,\n  queue                     text NOT NULL,\n  input                     text,\n  input_ref                 text,\n  retry_policy              jsonb NOT NULL,\n  status                    text NOT NULL,\n  idempotency_key           text NOT NULL,\n  not_before_ms             bigint NOT NULL,\n  dispatched_at_ms          bigint,\n  dispatch_attempts         integer NOT NULL DEFAULT 0,\n  dispatch_claimed_until_ms bigint,\n  lease_ttl_ms              bigint NOT NULL,\n  lease_until_ms            bigint,\n  worker_id                 text,\n  heartbeat_at_ms           bigint,\n  created_at_ms             bigint NOT NULL,\n  updated_at_ms             bigint NOT NULL,\n  UNIQUE (run_id, step_id),\n  UNIQUE (idempotency_key)\n);\n\n-- Outbox stage \"push tasks\".\nCREATE INDEX IF NOT EXISTS tasks_dispatch_idx\n  ON tasks (queue, not_before_ms)\n  WHERE status = 'scheduled' AND dispatched_at_ms IS NULL;\n\n-- Lease reaper.\nCREATE INDEX IF NOT EXISTS tasks_lease_idx\n  ON tasks (lease_until_ms) WHERE status = 'running';\n\nCREATE INDEX IF NOT EXISTS tasks_run_idx ON tasks (run_id);\n\nCREATE TABLE IF NOT EXISTS timers (\n  run_id           text NOT NULL REFERENCES runs (run_id) ON DELETE CASCADE,\n  step_id          text NOT NULL,\n  fire_at_ms       bigint NOT NULL,\n  fired_at_ms      bigint,\n  claimed_until_ms bigint,\n  PRIMARY KEY (run_id, step_id)\n);\n\nCREATE INDEX IF NOT EXISTS timers_due_idx\n  ON timers (fire_at_ms) WHERE fired_at_ms IS NULL;\n\nCREATE TABLE IF NOT EXISTS signal_waits (\n  run_id        text NOT NULL REFERENCES runs (run_id) ON DELETE CASCADE,\n  step_id       text NOT NULL,\n  name          text NOT NULL,\n  schema_ref    text,\n  expires_at_ms bigint,\n  PRIMARY KEY (run_id, step_id)\n);\n\nCREATE INDEX IF NOT EXISTS signal_waits_name_idx ON signal_waits (run_id, name);\n\nCREATE TABLE IF NOT EXISTS signals (\n  signal_id         text PRIMARY KEY,\n  run_id            text NOT NULL REFERENCES runs (run_id) ON DELETE CASCADE,\n  name              text NOT NULL,\n  payload           text,\n  payload_ref       text,\n  sender            text,\n  created_at_ms     bigint NOT NULL,\n  delivered_at_ms   bigint,\n  delivered_step_id text\n);\n\nCREATE INDEX IF NOT EXISTS signals_pending_idx\n  ON signals (run_id, name, created_at_ms) WHERE delivered_at_ms IS NULL;\n\nCREATE TABLE IF NOT EXISTS schemas (\n  name          text NOT NULL,\n  version       text NOT NULL,\n  json_schema   text NOT NULL,\n  retry_policy  text,\n  created_at_ms bigint NOT NULL,\n  PRIMARY KEY (name, version)\n);\n\nCREATE TABLE IF NOT EXISTS bundles (\n  digest         text PRIMARY KEY,\n  workflow       text NOT NULL,\n  kind           text NOT NULL,\n  blob_ref       text NOT NULL,\n  source_map_ref text,\n  created_at_ms  bigint NOT NULL\n);\n";
